const icons = {home,task,history,back,arrow,down,close,info,bolt,leaf,checkCircle,check,minus,partial,drop,recycle,paper,bike,more};

export function icon(name, className = '') {
 const nodes=icons[name];
 if(!nodes)throw new Error(`Unknown icon: ${name}`);
 const attrs={strokeLinecap:'stroke-linecap',strokeLinejoin:'stroke-linejoin',strokeWidth:'stroke-width',fillRule:'fill-rule',clipRule:'clip-rule'};
 return `<svg class="icon ${className}" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${nodes.map(([tag,props])=>`<${tag} ${Object.entries(props).filter(([key])=>key!=='key').map(([key,value])=>`${attrs[key]||key}="${key==='strokeWidth'?2:value}"`).join(' ')}/>`).join('')}</svg>`;
}
